import{_ as d,o as a,c as l,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Единое деление уровней культивации","description":"","frontmatter":{},"headers":[],"relativePath":"ru/14-修炼境界统一划分.md","filePath":"ru/14-修炼境界统一划分.md"}'),r={name:"ru/14-修炼境界统一划分.md"};function e(h,t,o,n,p,u){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="единое-деление-уровнеи-культивации" tabindex="-1">Единое деление уровней культивации <a class="header-anchor" href="#единое-деление-уровнеи-культивации" aria-label="Permalink to &quot;Единое деление уровней культивации&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>14</td></tr><tr><td>Модуль</td><td>Космические законы и системы культивации</td></tr><tr><td>Ключевые слова</td><td>Деление уровней, Единый стандарт, Девять уровней, Межсистемное сопоставление, Сертификация якорей</td></tr></tbody></table><h2 id="i-необходимость-единого-деления-уровнеи" tabindex="-1">I. Необходимость единого деления уровней <a class="header-anchor" href="#i-необходимость-единого-деления-уровнеи" aria-label="Permalink to &quot;I. Необходимость единого деления уровней&quot;">​</a></h2><p>До установления Симбиотической Цивилизации Якоря в Хэн Юаньчжоу существовали тысячи систем культивации, каждая со своими независимыми стандартами деления уровней. Хаотичная система уровней породила ряд проблем: силу практиков разных систем было трудно сравнивать, межсистемное общение и сотрудничество лишено общего языка, распределение ресурсов и оценка социального статуса лишены единой основы, возникла даже серьёзная несправедливость «одинаковый уровень — разная сила».</p><p>После установления цивилизации для решения проблемы под руководством «Комитета стандартов культивации» при Парламенте Республики Десяти Тысяч Рас совместно с представителями Трёхсот Систем был выработан «Единый стандарт деления уровней культивации». Стандарт основан не на названиях уровней какой-либо одной системы, а на четырёх центральных показателях — глубина понимания изначальных законов космоса, точность управления энергией, степень эволюции сознания, вклад в симбиотическую сеть, — создавая универсальную межсистемную систему деления уровней.</p><p>Центральный принцип — «ценить суть, а не название»: какой бы системой ни пользовался практик и как бы ни называл свои уровни, если суть достигла соответствующего уровня единого стандарта, он признаётся на этом уровне. Принцип обеспечивает справедливость и объективность оценки.</p><h2 id="ii-обзор-девяти-уровнеи" tabindex="-1">II. Обзор девяти уровней <a class="header-anchor" href="#ii-обзор-девяти-уровнеи" aria-label="Permalink to &quot;II. Обзор девяти уровней&quot;">​</a></h2><p>Единый стандарт делит эволюционный путь практика на девять великих уровней, от низшего к высшему:</p><table tabindex="0"><thead><tr><th>№</th><th>Название</th><th>Центральные характеристики</th><th>Примерное соответствие в Трёх Основах Истока</th><th>Социальная роль</th></tr></thead><tbody><tr><td>Первый</td><td>Уровень Ощущения Истока</td><td>Первоначальное восприятие космической энергии и законов, начало формальной культивации</td><td>Начальное прозрение / Ощущение Жизни / Познание Пространства</td><td>Начинающий</td></tr><tr><td>Второй</td><td>Уровень Сгущения Истока</td><td>Стабильное поглощение и сгущение энергии, базовая внутренняя циркуляция</td><td>Дедукция / Циркуляция / Владение Пространством</td><td>Младший практик</td></tr><tr><td>Третий</td><td>Уровень Превращения Истока</td><td>Высокая очистка энергии, превращение энергии в различные применения</td><td>Итерация / Порождаемость / Преображение Пространства</td><td>Средний практик</td></tr><tr><td>Четвёртый</td><td>Уровень Закона Истока</td><td>Начало понимания и управления законами, первичное слияние энергии и законов</td><td>Слияние / Жизненное Превращение / Закон Пространства</td><td>Продвинутый практик</td></tr><tr><td>Пятый</td><td>Уровень Дао Истока</td><td>Глубокое понимание законов одной сферы, формирование личного «Дао»</td><td>Исток / Рождение Истока / Исток Пространства</td><td>Мастер</td></tr><tr><td>Шестой</td><td>Уровень Слияния с Дао</td><td>Личное Дао глубоко сливается с изначальными законами космоса, каждое движение сообразно Дао</td><td>Выше пятого уровня одной системы</td><td>Грандмастер</td></tr><tr><td>Седьмой</td><td>Уровень Прорыва Границ</td><td>Прорыв ограничений законов планов, стабильные операции между планами</td><td>—</td><td>Эксперт уровня плана</td></tr><tr><td>Восьмой</td><td>Уровень Сотворения Мира</td><td>Сотворение полных миров и систем законов в Изолированном Пространстве</td><td>—</td><td>Эксперт уровня мира</td></tr><tr><td>Девятый</td><td>Уровень Истока</td><td>Касание Истока космоса, участие в тонкой настройке и оптимизации космических законов</td><td>—</td><td>Эксперт уровня космоса</td></tr></tbody></table><p>Из девяти уровней первый–пятый — «пять смертных уровней культивации», достижимые большинством практиков усердием; шестой–девятый — «четыре священных уровня», требующие исключительного таланта, удачи и усилий; прорыв каждого — событие космического масштаба.</p><h2 id="iii-подробные-стандарты-каждого-уровня" tabindex="-1">III. Подробные стандарты каждого уровня <a class="header-anchor" href="#iii-подробные-стандарты-каждого-уровня" aria-label="Permalink to &quot;III. Подробные стандарты каждого уровня&quot;">​</a></h2><h3 id="_3-1-первыи-уровень-ощущение-истока" tabindex="-1">3.1 Первый уровень: Ощущение Истока <a class="header-anchor" href="#_3-1-первыи-уровень-ощущение-истока" aria-label="Permalink to &quot;3.1 Первый уровень: Ощущение Истока&quot;">​</a></h3><p>Уровень Ощущения Истока — исходная точка культивации, ядро — «восприятие». Стандарты достижения:</p><ul><li>Стабильное восприятие свободной энергии космоса (духовное ци, сила законов и т.д.)</li><li>Поглощение малых количеств энергии в тело базовыми методами</li><li>Первичное энергетическое сознание, различение типов энергии</li><li>Начальное улучшение физических качеств от энергетического пропитывания</li></ul><p>Практики уровня — «начинающие» в обществе, главная задача — заложить основу и найти подходящую систему. Прорыв требует от нескольких недель до нескольких месяцев формальной культивации.</p><h3 id="_3-2-второи-уровень-сгущение-истока" tabindex="-1">3.2 Второй уровень: Сгущение Истока <a class="header-anchor" href="#_3-2-второи-уровень-сгущение-истока" aria-label="Permalink to &quot;3.2 Второй уровень: Сгущение Истока&quot;">​</a></h3><p>Ядро — «сгущение». Стандарты:</p><ul><li>Стабильное поглощение космической энергии и сгущение в полезные запасы в теле</li><li>Базовая внутренняя циркуляция по определённым путям</li><li>Использование сгущённой энергии для базовых атак, защиты или помощи</li><li>Чистота энергии достигает базового стандарта, без излишних примесей</li></ul><p>Практики уже обладают базовой идентичностью культиватора, могут участвовать в низших задачах и социальных услугах. Прорыв — от нескольких месяцев до нескольких лет.</p><h3 id="_3-3-третии-уровень-превращение-истока" tabindex="-1">3.3 Третий уровень: Превращение Истока <a class="header-anchor" href="#_3-3-третии-уровень-превращение-истока" aria-label="Permalink to &quot;3.3 Третий уровень: Превращение Истока&quot;">​</a></h3><p>Ядро — «превращение». Стандарты:</p><ul><li>Высокая очистка энергии, превращение одного типа энергии в другой</li><li>Первичное взаимодействие энергии и материи (энергоприсоединение, энергоформовка)</li><li>Стабильная эффективная внутренняя циркуляция, резкий рост скорости восстановления</li><li>Начало восприятия существования и действия законов</li></ul><p>Практики — костяк общества: средние наставники, технический персонал, низовые руководители. Прорыв — от нескольких лет до более десятилетия.</p><h3 id="_3-4-четвертыи-уровень-закон-истока" tabindex="-1">3.4 Четвёртый уровень: Закон Истока <a class="header-anchor" href="#_3-4-четвертыи-уровень-закон-истока" aria-label="Permalink to &quot;3.4 Четвёртый уровень: Закон Истока&quot;">​</a></h3><p>Ядро — «закон». Стандарты:</p><ul><li>Понимание и первичное управление базовыми законами одной сферы</li><li>Первичное слияние энергии и законов, рождение «силы закона» — высшей формы энергии</li><li>Исполнение заклинаний и навыков на основе законов</li><li>Резкий рост интенсивности сознания, долгие глубокие дедукции и медитации</li></ul><p>Практики — продвинутые кадры: старшие наставники, технические эксперты, средние руководители. Прорыв — от более десятилетия до нескольких десятилетий; первый крупный барьер в жизни многих.</p><h3 id="_3-5-пятыи-уровень-дао-истока" tabindex="-1">3.5 Пятый уровень: Дао Истока <a class="header-anchor" href="#_3-5-пятыи-уровень-дао-истока" aria-label="Permalink to &quot;3.5 Пятый уровень: Дао Истока&quot;">​</a></h3><p>Ядро — «становление Дао». Стандарты:</p><ul><li>Системное глубокое понимание законов одной сферы, формирование личного уникального «Дао»</li><li>Резонанс личного Дао с космическими законами, мобилизация силы законов на большом охвате</li><li>Глубокое слияние энергии и законов, каждое движение содержит силу законов</li><li>Эволюция сознания на высший уровень, межплановая перцепция сознания</li></ul><p>Практики — «мастера» цивилизации, авторитеты в своих сферах: советники уровня цивилизации, великие наставники, высшие руководители. Прорыв требует исключительного таланта и озарения; многие не достигают за жизнь.</p><h3 id="_3-6-шестои-уровень-слияние-с-дао" tabindex="-1">3.6 Шестой уровень: Слияние с Дао <a class="header-anchor" href="#_3-6-шестои-уровень-слияние-с-дао" aria-label="Permalink to &quot;3.6 Шестой уровень: Слияние с Дао&quot;">​</a></h3><p>Ядро — «слияние с Дао». Стандарты:</p><ul><li>Глубокое слияние личного Дао с изначальными законами космоса, состояние «единства неба и человека»</li><li>Переписывание действия локальных законов на большом охвате</li><li>Эволюция формы жизни к высшим измерениям, частичное освобождение от материального тела</li><li>Создание стабильного личного домена (домена законов)</li></ul><p>Практики — «грандмастера» цивилизации, вершины сфер, с большим влиянием на направление развития. Прорыв — событие космического масштаба, требует единства времени, места и людей.</p><h3 id="_3-7-седьмои-уровень-прорыв-границ" tabindex="-1">3.7 Седьмой уровень: Прорыв Границ <a class="header-anchor" href="#_3-7-седьмои-уровень-прорыв-границ" aria-label="Permalink to &quot;3.7 Седьмой уровень: Прорыв Границ&quot;">​</a></h3><p>Ядро — «прорыв границ». Стандарты:</p><ul><li>Прорыв ограничений законов планов, переход между планами без поддержки якорей</li><li>Операции с мембраной планов: открытие каналов, ремонт трещин</li><li>Расширение личного домена в малое независимое пространство</li><li>Дальнейшая высокомерность формы жизни, выживание в средах разных планов</li></ul><p>Эксперты — «уровень плана», самостоятельно выполняют задачи плана. Прорыв крайне труден; число достигших во всём Хэн Юаньчжоу ограничено.</p><h3 id="_3-8-восьмои-уровень-сотворение-мира" tabindex="-1">3.8 Восьмой уровень: Сотворение Мира <a class="header-anchor" href="#_3-8-восьмои-уровень-сотворение-мира" aria-label="Permalink to &quot;3.8 Восьмой уровень: Сотворение Мира&quot;">​</a></h3><p>Ядро — «сотворение мира». Стандарты:</p><ul><li>Сотворение полных миров в Изолированном Пространстве: материя, энергия, законы, жизнь</li><li>Проектирование базовых систем законов новых миров</li><li>Расширение личного домена в полный мир</li><li>Форма жизни приближается к высокомерному бытию, одновременное проявление в нескольких планах</li></ul><p>Эксперты — «уровень мира»; сотворённые миры служат ресурсами культивации, площадками экспериментов, убежищами цивилизации. Прорыв — одно из редчайших событий космоса.</p><h3 id="_3-9-девятыи-уровень-исток" tabindex="-1">3.9 Девятый уровень: Исток <a class="header-anchor" href="#_3-9-девятыи-уровень-исток" aria-label="Permalink to &quot;3.9 Девятый уровень: Исток&quot;">​</a></h3><p>Ядро — «Исток». Стандарты:</p><ul><li>Касание изначальных законов космоса, понимание предельных законов его работы</li><li>Участие в тонкой настройке законов, влияние на эволюционное направление космоса</li><li>Глубокая связь формы жизни с Истоком космоса, почти бессмертие</li><li>Мобилизация силы Истока в космическом масштабе</li></ul><p>Эксперты — «уровень космоса», верховная сила Хэн Юаньчжоу. Достигшие обычно именуются «верховными экспертами планов» — центральная целевая группа «стратегии активации 20%».</p><h2 id="iv-механизм-сертификации-уровнеи" tabindex="-1">IV. Механизм сертификации уровней <a class="header-anchor" href="#iv-механизм-сертификации-уровнеи" aria-label="Permalink to &quot;IV. Механизм сертификации уровней&quot;">​</a></h2><p>Для справедливости и точности оценок цивилизация установила строгий механизм сертификации:</p><ol><li><strong>Автоматический мониторинг якорей</strong>: после подключения к сети якорей якорь непрерывно отслеживает уровень энергии, понимание законов, интенсивность сознания; при достижении стандарта нового уровня автоматически уведомляет</li><li><strong>Оценка Комитета стандартов</strong>: прорывы четвёртого уровня и выше требуют формальной оценки Комитетом — теория, практический бой, оценка вклада</li><li><strong>Оглашение и период возражений</strong>: после успеха — тридцатидневное оглашение; любое существо может возразить; при подтверждении возражения — повторная оценка</li><li><strong>Выдача сертификата</strong>: при отсутствии возражений сеть якорей выдаёт единый сертификат, данные вносятся в базу цивилизации</li></ol><h2 id="v-уровни-и-социальные-права-и-обязанности" tabindex="-1">V. Уровни и социальные права и обязанности <a class="header-anchor" href="#v-уровни-и-социальные-права-и-обязанности" aria-label="Permalink to &quot;V. Уровни и социальные права и обязанности&quot;">​</a></h2><p>Практики разных уровней имеют разные права и несут разные обязанности:</p><table tabindex="0"><thead><tr><th>Уровень</th><th>Центральные права</th><th>Центральные обязанности</th></tr></thead><tbody><tr><td>Ощущение–Сгущение Истока</td><td>Бесплатные базовые ресурсы, доступ к общественным площадкам</td><td>Соблюдение этики, участие в базовых услугах сообщества</td></tr><tr><td>Превращение–Закон Истока</td><td>Продвинутые ресурсы, право заявки на наставничество, межрегиональная мобильность</td><td>Наставничество новичков, участие в разработках или услугах</td></tr><tr><td>Дао–Слияние с Дао</td><td>Высокие ресурсы, доступ к высшим уровням якорей, участие в решениях цивилизации</td><td>Исследовательские проекты уровня цивилизации, стабильность региональных якорей</td></tr><tr><td>Прорыв Границ–Сотворение Мира</td><td>Ресурсы уровня плана, создание независимых пространств, участие в делах планов</td><td>Задачи уровня плана, стабильность мембран, межплановые дела</td></tr><tr><td>Исток</td><td>Ресурсы уровня космоса, участие в настройке законов, высшие решения цивилизации</td><td>Стабильность космоса, направление эволюции, подготовка кадров</td></tr></tbody></table><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Единый стандарт деления уровней — одна из инфраструктур системы культивации Симбиотической Цивилизации Якоря. Он даёт Трёмстам Системам общее «мерило», делая возможными межсистемное общение, сотрудничество и состязание, и даёт объективную основу распределению ресурсов, социальному управлению и подготовке кадров. Деление на девять уровней — не для создания иерархии, а для ясной отметки эволюционного этапа каждого практика и предоставления ему наилучшей поддержки. Повышение уровня — не конец, а новая точка старта к высшей симбиотической эволюции.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (Обзор Трёхсот Изначальных Систем Культивации)</li><li>17-位面至高强者标准 (Стандарты верховных экспертов планов)</li><li>29-共生度评估体系 (Система оценки степени симбиоза)</li></ul>',57)])])}const _=d(r,[["render",e]]);export{b as __pageData,_ as default};
